<?php require 'includes/auth.php';require_role('customer');$customerId=get_entity_id('customer',(int)current_user()['user_id']);$packageId=(int)($_REQUEST['package_id']??0);$pstmt=db()->prepare("SELECT * FROM packages WHERE package_id=? AND status='active'");$pstmt->execute([$packageId]);$package=$pstmt->fetch();if(!$package){flash('error','That package is unavailable.');redirect('packages.php');}$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$start=post('start_date');$end=post('end_date');$travelers=(int)post('travelers');$hotelId=(int)post('hotel_id');$roomId=(int)post('room_id');$rooms=(int)post('number_of_rooms');$transport=isset($_POST['transport']);$pickup=post('pickup_location');$special=post('special_request');try{if(!$start||!$end||days_between($start,$end)<1)throw new RuntimeException('End date must be after start date.');if($start<date('Y-m-d'))throw new RuntimeException('Start date cannot be in the past.');if($travelers<1||$travelers>$package['max_travelers'])throw new RuntimeException('Traveler count is not valid for this package.');$nights=days_between($start,$end);$hotelTotal=0;$hotelStatus='Not Required';if($hotelId||$roomId){if(!$hotelId||!$roomId||$rooms<1)throw new RuntimeException('Choose a hotel, room type and number of rooms.');$s=db()->prepare("SELECT r.*,h.status hotel_status FROM rooms r JOIN hotels h ON h.hotel_id=r.hotel_id WHERE r.room_id=? AND r.hotel_id=? FOR UPDATE");$pdo=db();$pdo->beginTransaction();$s->execute([$roomId,$hotelId]);$room=$s->fetch();if(!$room||$room['status']!=='active'||$room['hotel_status']!=='active'||$room['available_rooms']<$rooms)throw new RuntimeException('The selected room is unavailable.');if($travelers>$room['capacity']*$rooms)throw new RuntimeException('Selected rooms do not have enough capacity.');$hotelTotal=$room['price_per_night']*$rooms*$nights;$hotelStatus='Pending';}else{$rooms=0;$pdo=db();$pdo->beginTransaction();}$driverTotal=$transport?30000:0;if($transport&&!$pickup)throw new RuntimeException('Enter a pickup location for transportation.');$packageTotal=$package['price_per_person']*$travelers;$total=$packageTotal+$hotelTotal+$driverTotal;$s=$pdo->prepare('INSERT INTO bookings(customer_id,package_id,hotel_id,room_id,start_date,end_date,number_of_travelers,number_of_rooms,pickup_location,special_request,package_total,hotel_total,driver_total,total_amount,hotel_reservation_status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$s->execute([$customerId,$packageId,$hotelId?:null,$roomId?:null,$start,$end,$travelers,$rooms,$pickup?:null,$special?:null,$packageTotal,$hotelTotal,$driverTotal,$total,$hotelStatus]);$bid=(int)$pdo->lastInsertId();if(isset($room)){$pdo->prepare('UPDATE rooms SET available_rooms=available_rooms-? WHERE room_id=?')->execute([$rooms,$roomId]);}$pdo->commit();flash('success','Booking request submitted. Add your payment record next.');redirect('customer/booking-details.php?id='.$bid);}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$errors[]=$e instanceof RuntimeException?$e->getMessage():'Unable to create booking. Please try again.';}}$hotels=db()->query("SELECT hotel_id,hotel_name,city FROM hotels WHERE status='active' ORDER BY city,hotel_name")->fetchAll();$roomRows=db()->query("SELECT r.room_id,r.hotel_id,r.room_type,r.capacity,r.price_per_night,r.available_rooms FROM rooms r JOIN hotels h ON h.hotel_id=r.hotel_id WHERE r.status='active' AND h.status='active' AND r.available_rooms>0 ORDER BY r.hotel_id,r.price_per_night")->fetchAll();$pageTitle='Book '.$package['package_name'];require 'includes/header.php';?><div class="container py-5"><div class="row g-4"><div class="col-lg-8"><h2>Book <?=e($package['package_name'])?></h2><p class="text-muted">Prices are recalculated securely when you submit.</p><?php foreach($errors as $e):?><div class="alert alert-danger"><?=e($e)?></div><?php endforeach;?><form method="post" class="card card-body needs-validation" novalidate><?=csrf_field()?><input type="hidden" name="package_id" value="<?=$packageId?>"><div class="row g-3"><div class="col-md-6"><label class="form-label">Start date</label><input type="date" name="start_date" min="<?=date('Y-m-d')?>" class="form-control" required></div><div class="col-md-6"><label class="form-label">End date</label><input type="date" name="end_date" min="<?=date('Y-m-d',strtotime('+1 day'))?>" class="form-control" required></div><div class="col-md-6"><label class="form-label">Travelers (max <?=e($package['max_travelers'])?>)</label><input type="number" name="travelers" min="1" max="<?=e($package['max_travelers'])?>" value="1" class="form-control" required></div><div class="col-md-6"><label class="form-label">Accommodation</label><select class="form-select" name="hotel_id" id="hotel"><option value="">No hotel required</option><?php foreach($hotels as $h):?><option value="<?=$h['hotel_id']?>"><?=e($h['hotel_name'])?> — <?=e($h['city'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Room type</label><select class="form-select" name="room_id" id="room"><option value="">Select a hotel first</option><?php foreach($roomRows as $r):?><option value="<?=$r['room_id']?>" data-hotel="<?=$r['hotel_id']?>" hidden><?=e($r['room_type'])?> · <?=money($r['price_per_night'])?>/night (<?=$r['available_rooms']?> left, cap <?=e($r['capacity'])?>)</option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Number of rooms</label><input type="number" name="number_of_rooms" min="1" value="1" class="form-control"></div><div class="col-12"><div class="form-check"><input class="form-check-input" type="checkbox" name="transport" id="transport"><label class="form-check-label" for="transport">Request transportation (+<?=money(30000)?> coordination fee)</label></div></div><div class="col-12"><label class="form-label">Pickup location</label><input class="form-control" name="pickup_location" placeholder="Required when transportation is selected"></div><div class="col-12"><label class="form-label">Special request</label><textarea class="form-control" name="special_request" rows="3"></textarea></div><div class="col-12"><button class="btn btn-warning">Submit booking request</button></div></div></form></div><aside class="col-lg-4"><div class="card card-body booking-summary"><h4><?=e($package['package_name'])?></h4><p><?=e($package['duration_days'])?> days / <?=e($package['duration_nights'])?> nights</p><h3 class="text-primary"><?=money($package['price_per_person'])?></h3><small>per person; server-calculated at submission</small></div></aside></div></div><script>document.getElementById('hotel').addEventListener('change',function(){for(const o of document.querySelectorAll('#room option[data-hotel]'))o.hidden=o.dataset.hotel!==this.value;document.getElementById('room').value='';});</script><?php require 'includes/footer.php'; ?>
